1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>autom9-extension — Function Dependency Graph</title>
7	  <script src="https://d3js.org/d3.v7.min.js"></script>
8	  <style>
9	    * { box-sizing: border-box; margin: 0; padding: 0; }
10	    body {
11	      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
12	      background: #0d1117; color: #e2e8f0;
13	      display: flex; flex-direction: column; height: 100vh; overflow: hidden;
14	    }
15	
16	    /* ── Header ── */
17	    #header {
18	      padding: 10px 20px; background: #161b22;
19	      border-bottom: 1px solid #21262d;
20	      display: flex; align-items: center; gap: 16px; flex-shrink: 0;
21	    }
22	    #header h1 { font-size: 15px; font-weight: 600; color: #f0f6fc; }
23	    #header .sub { font-size: 11px; color: #6e7681; margin-top: 2px; }
24	    #legend { display: flex; gap: 14px; margin-left: auto; }
25	    .leg { display: flex; align-items: center; gap: 6px; font-size: 11px; color: #8b949e; }
26	    .leg-dot { width: 9px; height: 9px; border-radius: 50%; }
27	
28	    /* ── Layout ── */
29	    #main { display: flex; flex: 1; overflow: hidden; }
30	
31	    /* ── Sidebar ── */
32	    #sidebar {
33	      width: 240px; background: #161b22;
34	      border-right: 1px solid #21262d;
35	      overflow-y: auto; flex-shrink: 0;
36	      scrollbar-width: thin; scrollbar-color: #30363d transparent;
37	    }
38	    #sidebar::-webkit-scrollbar { width: 4px; }
39	    #sidebar::-webkit-scrollbar-thumb { background: #30363d; border-radius: 2px; }
40	    .sb-cat-header {
41	      padding: 6px 12px; font-size: 10px; font-weight: 700;
42	      text-transform: uppercase; letter-spacing: 0.08em;
43	      border-bottom: 1px solid #21262d; background: #0d1117;
44	    }
45	    .sb-file { border-bottom: 1px solid #161b22; }
46	    .sb-file-hdr {
47	      padding: 7px 12px; font-size: 11px; cursor: pointer;
48	      display: flex; align-items: flex-start; gap: 8px;
49	    }
50	    .sb-file-hdr:hover { background: #1c2128; }
51	    .sb-dot { width: 7px; height: 7px; border-radius: 50%; flex-shrink: 0; margin-top: 3px; }
52	    .sb-fname { color: #c9d1d9; font-size: 11px; }
53	    .sb-fpath { color: #484f58; font-size: 10px; margin-top: 1px; }
54	    .sb-fns { padding: 0 0 4px 0; }
55	    .sb-fn {
56	      padding: 4px 12px 4px 28px; font-size: 11px; color: #6e7681;
57	      cursor: pointer; font-family: ui-monospace, SFMono-Regular, monospace;
58	    }
59	    .sb-fn:hover { background: #1c2128; color: #c9d1d9; }
60	    .sb-fn.active { background: #1f2937; color: #79c0ff; }
61	
62	    /* ── Graph canvas ── */
63	    #canvas { flex: 1; position: relative; overflow: hidden; background: #0d1117; }
64	    svg { width: 100%; height: 100%; }
65	
66	    /* ── SVG elements ── */
67	    .col-bg { fill: rgba(255,255,255,0.015); stroke: none; rx: 12; }
68	    .col-lbl { font-size: 10px; font-weight: 700; letter-spacing: 0.08em; fill-opacity: 0.35; }
69	
70	    .edge { fill: none; stroke-opacity: 0.45; transition: stroke-opacity 0.15s; }
71	    .edge.hi { stroke-opacity: 1 !important; stroke-width: 2px !important; }
72	    .edge.dim { stroke-opacity: 0.07 !important; }
73	    .edge-lbl { font-size: 8.5px; fill: #3a404a; pointer-events: none; }
74	    .edge-lbl.hi { fill: #6e7681 !important; }
75	    .edge-lbl.dim { opacity: 0.15 !important; }
76	
77	    .node-g { cursor: pointer; }
78	    .node-circle { transition: filter 0.15s; }
79	    .node-g:hover .node-circle { filter: brightness(1.3); }
80	    .node-g.hi .node-circle { filter: drop-shadow(0 0 7px var(--nc)) brightness(1.2); stroke-width: 2.5px !important; }
81	    .node-g.dim .node-circle { opacity: 0.18; }
82	    .node-g.dim .node-txt { opacity: 0.12; }
83	    .node-txt { pointer-events: none; }
84	
85	    /* ── Tooltip ── */
86	    #tip {
87	      position: absolute; display: none;
88	      background: #161b22; border: 1px solid #30363d;
89	      border-radius: 8px; padding: 10px 13px; font-size: 11px;
90	      max-width: 270px; z-index: 50; pointer-events: none;
91	      box-shadow: 0 8px 24px rgba(0,0,0,0.5);
92	    }
93	    #tip .t-title { font-weight: 600; color: #f0f6fc; margin-bottom: 2px; font-family: monospace; font-size: 12px; }
94	    #tip .t-file { color: #484f58; font-size: 10px; margin-bottom: 6px; }
95	    #tip .t-desc { color: #8b949e; line-height: 1.45; margin-bottom: 6px; }
96	    #tip .t-section { margin-top: 6px; }
97	    #tip .t-sec-lbl { font-size: 9px; text-transform: uppercase; letter-spacing: 0.06em; color: #3a404a; margin-bottom: 3px; }
98	    #tip .t-row { color: #6e7681; font-family: monospace; font-size: 10px; }
99	    #tip .t-row span { color: #484f58; }
100	
101	    /* ── Controls ── */
102	    #controls { position: absolute; bottom: 14px; right: 14px; display: flex; gap: 6px; }
103	    .cbtn {
104	      background: #161b22; border: 1px solid #30363d; color: #8b949e;
105	      padding: 5px 11px; border-radius: 6px; cursor: pointer; font-size: 11px;
106	    }
107	    .cbtn:hover { background: #1c2128; color: #c9d1d9; }
108	
109	    #search-wrap { position: absolute; top: 10px; right: 14px; }
110	    #search-wrap input {
111	      background: #161b22; border: 1px solid #30363d; color: #c9d1d9;
112	      padding: 5px 11px; border-radius: 6px; font-size: 11px; width: 190px; outline: none;
113	    }
114	    #search-wrap input:focus { border-color: #58a6ff; }
115	    #search-wrap input::placeholder { color: #3a404a; }
116	  </style>
117	</head>
118	<body>
119	<div id="header">
120	  <div>
121	    <div class="sub" style="display:flex; gap:6px; align-items:center">
122	      <span style="font-size:14px; font-weight:600; color:#f0f6fc">autom9-extension</span>
123	      <span style="color:#30363d">|</span>
124	      Function-level dependency graph
125	    </div>
126	    <div class="sub" style="margin-top:3px">Hover for details · Click node or sidebar item to trace dependencies · Drag to rearrange</div>
127	  </div>
128	  <div id="legend">
129	    <div class="leg"><div class="leg-dot" style="background:#f87171"></div>Entry</div>
130	    <div class="leg"><div class="leg-dot" style="background:#34d399"></div>Library</div>
131	    <div class="leg"><div class="leg-dot" style="background:#60a5fa"></div>Store</div>
132	    <div class="leg"><div class="leg-dot" style="background:#a78bfa"></div>Component</div>
133	  </div>
134	</div>
135	
136	<div id="main">
137	  <div id="sidebar"><div id="sb-body"></div></div>
138	  <div id="canvas">
139	    <svg id="svg"></svg>
140	    <div id="tip"></div>
141	    <div id="search-wrap"><input id="q" type="text" placeholder="Search functions…"></div>
142	    <div id="controls">
143	      <button class="cbtn" id="btn-reset">Reset</button>
144	      <button class="cbtn" id="btn-fit">Fit All</button>
145	    </div>
146	  </div>
147	</div>
148	
149	<script>
150	// ═══════════════════════════════════════════════════════
151	// DATA
152	// ═══════════════════════════════════════════════════════
153	
154	const CAT = {
155	  entry:     { label: 'Entry',     color: '#f87171', colX: 0.12 },
156	  lib:       { label: 'Library',   color: '#34d399', colX: 0.32 },
157	  store:     { label: 'Store',     color: '#60a5fa', colX: 0.55 },
158	  component: { label: 'Component', color: '#a78bfa', colX: 0.78 },
159	};
160	
161	const FILES = [
162	  { id: 'main.ts',                      path: 'src/main.ts',                              cat: 'entry',     label: 'main.ts' },
163	  { id: 'App.svelte',                   path: 'src/App.svelte',                           cat: 'entry',     label: 'App.svelte' },
