352	  { s: 'ChatPanel.svelte::confirmAction',       t: 'api.ts::apiFetch',                       lbl: 'POST /api/chat (confirm)' },
353	  { s: 'ChatPanel.svelte::confirmAction',       t: 'session.svelte.ts::sessionStore',        lbl: 'reads sessionId' },
354	  { s: 'ChatPanel.svelte::confirmAction',       t: 'chat.svelte.ts::chatStore',              lbl: 'clears + writes' },
355	  { s: 'ChatPanel.svelte::cancelAction',        t: 'chat.svelte.ts::chatStore',              lbl: 'clearPendingAction' },
356	
357	  // MessageList / ActionConfirm
358	  { s: 'MessageList.svelte::render',            t: 'chat.svelte.ts::chatStore',              lbl: 'reads messages[]' },
359	  { s: 'ActionConfirm.svelte::render',          t: 'chat.svelte.ts::chatStore',              lbl: 'reads pendingAction' },
360	];
361	
362	// ═══════════════════════════════════════════════════════
363	// SIDEBAR BUILD
364	// ═══════════════════════════════════════════════════════
365	const catOrder = ['entry', 'lib', 'store', 'component'];
366	const sbBody = document.getElementById('sb-body');
367	
368	catOrder.forEach(cat => {
369	  const catFiles = FILES.filter(f => f.cat === cat);
370	  if (!catFiles.length) return;
371	
372	  const hdr = document.createElement('div');
373	  hdr.className = 'sb-cat-header';
374	  hdr.style.color = CAT[cat].color;
375	  hdr.textContent = CAT[cat].label;
376	  sbBody.appendChild(hdr);
377	
378	  catFiles.forEach(file => {
379	    const wrap = document.createElement('div');
380	    wrap.className = 'sb-file';
381	    wrap.dataset.fid = file.id;
382	
383	    const fhdr = document.createElement('div');
384	    fhdr.className = 'sb-file-hdr';
385	    fhdr.innerHTML = `<div class="sb-dot" style="background:${CAT[cat].color}"></div>
386	      <div><div class="sb-fname">${file.label}</div><div class="sb-fpath">${file.path}</div></div>`;
387	    fhdr.addEventListener('click', () => highlightFile(file.id));
388	    wrap.appendChild(fhdr);
389	
390	    const fns = NODES.filter(n => n.file === file.id);
391	    if (fns.length) {
392	      const ul = document.createElement('div');
393	      ul.className = 'sb-fns';
394	      fns.forEach(fn => {
395	        const li = document.createElement('div');
396	        li.className = 'sb-fn';
397	        li.dataset.nid = fn.id;
398	        li.textContent = fn.label;
399	        li.addEventListener('click', e => { e.stopPropagation(); toggleNode(fn.id); });
400	        ul.appendChild(li);
401	      });
402	      wrap.appendChild(ul);
403	    }
404	    sbBody.appendChild(wrap);
405	  });
406	});
407	
408	// ═══════════════════════════════════════════════════════
409	// D3 GRAPH
410	// ═══════════════════════════════════════════════════════
411	const container = document.getElementById('canvas');
412	const W = () => container.offsetWidth;
413	const H = () => container.offsetHeight;
414	
415	const svg = d3.select('#svg');
416	const g   = svg.append('g');
417	
418	// ── Arrowhead markers ─────────────────────────────────
419	const defs = svg.append('defs');
420	Object.entries(CAT).forEach(([key, cfg]) => {
421	  ['', '-hi'].forEach(suffix => {
422	    defs.append('marker')
423	      .attr('id', `arr-${key}${suffix}`)
424	      .attr('viewBox', '0 -4 8 8')
425	      .attr('refX', 8)
426	      .attr('refY', 0)
427	      .attr('markerWidth', 5)
428	      .attr('markerHeight', 5)
429	      .attr('orient', 'auto')
430	      .append('path')
431	      .attr('d', 'M0,-4L8,0L0,4')
432	      .attr('fill', cfg.color)
433	      .attr('opacity', suffix ? 1 : 0.6);
434	  });
435	});
436	
437	// ── Column background strips ──────────────────────────
438	const colData = Object.entries(CAT).map(([k, v]) => ({ key: k, ...v }));
439	const colBg = g.append('g').attr('class', 'col-bgs');
440	const colLbls = g.append('g').attr('class', 'col-lbls');
441	
442	// ── Node + link data ──────────────────────────────────
443	const nodeById = new Map(NODES.map(n => [n.id, { ...n }]));
444	
445	const linkData = LINKS.map(l => ({
446	  ...l,
447	  source: nodeById.get(l.s),
448	  target: nodeById.get(l.t),
449	})).filter(l => l.source && l.target);
450	
451	// ── Assign initial x based on category column ─────────
452	NODES.forEach(n => {
453	  n.x = CAT[n.cat].colX * W() + (Math.random() - 0.5) * 60;
454	  n.y = H() / 2 + (Math.random() - 0.5) * (H() * 0.7);
455	});
456	const nodeData = NODES;
457	
458	// ── Force simulation ──────────────────────────────────
459	const sim = d3.forceSimulation(nodeData)
460	  .force('link',    d3.forceLink(linkData).id(d => d.id).distance(140).strength(0.25))
461	  .force('charge',  d3.forceManyBody().strength(-320))
462	  .force('collide', d3.forceCollide(38))
463	  .force('x',       d3.forceX(d => CAT[d.cat].colX * W()).strength(0.55))
464	  .force('y',       d3.forceY(d => H() / 2).strength(0.05));
465	
466	// ── Edge count per pair (for curved offsets) ──────────
467	const pairCount = new Map();
468	const pairIndex = new Map();
469	linkData.forEach(l => {
470	  const key = [l.source.id, l.target.id].sort().join('||');
471	  pairCount.set(key, (pairCount.get(key) || 0) + 1);
472	});
473	const tempCount = new Map();
474	linkData.forEach(l => {
475	  const key = [l.source.id, l.target.id].sort().join('||');
476	  const idx = tempCount.get(key) || 0;
477	  pairIndex.set(l, idx);
478	  tempCount.set(key, idx + 1);
479	});
480	
481	// ── Draw edges ────────────────────────────────────────
482	const edgeG = g.append('g').attr('class', 'edges');
483	const edgeSel = edgeG.selectAll('g').data(linkData).enter().append('g');
484	
485	const edgePath = edgeSel.append('path')
486	  .attr('class', 'edge')
487	  .attr('stroke', d => CAT[d.source.cat]?.color || '#4a5568')
488	  .attr('stroke-width', 1.2)
489	  .attr('marker-end', d => `url(#arr-${d.source.cat})`);
490	
491	const edgeLbl = edgeSel.append('text')
492	  .attr('class', 'edge-lbl')
493	  .text(d => d.lbl);
494	
495	// ── Draw nodes ────────────────────────────────────────
496	const R = 16; // circle radius
497	
498	const nodeG = g.append('g').attr('class', 'nodes')
499	  .selectAll('g')
500	  .data(nodeData)
501	  .enter().append('g')
502	  .attr('class', 'node-g')
503	  .style('--nc', d => CAT[d.cat].color)
504	  .call(d3.drag()
505	    .on('start', (e, d) => { if (!e.active) sim.alphaTarget(0.3).restart(); d.fx = d.x; d.fy = d.y; })
506	    .on('drag',  (e, d) => { d.fx = e.x; d.fy = e.y; })
507	    .on('end',   (e, d) => { if (!e.active) sim.alphaTarget(0); d.fx = null; d.fy = null; }))
508	  .on('click', (e, d) => { e.stopPropagation(); toggleNode(d.id); })
509	  .on('mouseover', showTip)
510	  .on('mousemove', moveTip)
511	  .on('mouseout',  hideTip);
512	
513	nodeG.append('circle')
514	  .attr('class', 'node-circle')
515	  .attr('r', R)
516	  .attr('fill', d => CAT[d.cat].color + '22')
517	  .attr('stroke', d => CAT[d.cat].color)
518	  .attr('stroke-width', 1.5);
519	
520	// Short label inside circle
521	nodeG.append('text')
522	  .attr('class', 'node-txt')
523	  .attr('dy', 3)
524	  .attr('text-anchor', 'middle')
525	  .attr('font-size', '8px')
526	  .attr('font-family', 'ui-monospace, SFMono-Regular, monospace')
527	  .attr('fill', d => CAT[d.cat].color)
528	  .text(d => {
529	    const s = d.label.replace(/\(\)$/, '').replace(/^(.*)\s/, '$1');
530	    return s.length > 9 ? s.slice(0, 8) + '…' : s;
531	  });
532	
533	// Label below circle
534	nodeG.append('text')
535	  .attr('class', 'node-txt')
536	  .attr('dy', R + 12)
537	  .attr('text-anchor', 'middle')
538	  .attr('font-size', '9px')
539	  .attr('font-family', 'ui-monospace, SFMono-Regular, monospace')
540	  .attr('fill', '#8b949e')
541	  .text(d => d.label);
542	
543	// ── Tick ──────────────────────────────────────────────
544	sim.on('tick', () => {
545	  edgePath.attr('d', d => {
546	    const sx = d.source.x, sy = d.source.y;
547	    const tx = d.target.x, ty = d.target.y;
548	    const dx = tx - sx, dy = ty - sy;
549	    const dist = Math.hypot(dx, dy) || 1;
550	    const nx = dx / dist, ny = dy / dist;
551	
552	    // Shorten at target to stop at circle edge
553	    const ex = tx - nx * (R + 3);
554	    const ey = ty - ny * (R + 3);
555	    // Shorten at source too
556	    const bx = sx + nx * (R + 3);
557	    const by = sy + ny * (R + 3);
558	
559	    // Curved offset for multi-edges between same pair
560	    const key = [d.source.id, d.target.id].sort().join('||');
561	    const total = pairCount.get(key) || 1;
562	    const idx   = pairIndex.get(d) || 0;
563	    const offset = total > 1 ? ((idx - (total - 1) / 2) * 28) : 0;
564	
565	    const mx = (bx + ex) / 2 - ny * offset;
566	    const my = (by + ey) / 2 + nx * offset;
567	    return `M${bx},${by} Q${mx},${my} ${ex},${ey}`;
568	  });
569	
570	  edgeLbl
571	    .attr('x', d => (d.source.x + d.target.x) / 2)
572	    .attr('y', d => (d.source.y + d.target.y) / 2 - 5);
573	
574	  nodeG.attr('transform', d => `translate(${d.x},${d.y})`);
575	
576	  updateColBgs();
577	});
578	
579	// ── Column background rectangles ─────────────────────
580	function updateColBgs() {
581	  const catGroups = d3.group(nodeData, d => d.cat);
582	  const rects = colData.map(col => {
583	    const ns = catGroups.get(col.key) || [];
584	    if (!ns.length) return null;
585	    const xs = ns.map(n => n.x), ys = ns.map(n => n.y);
586	    const pad = 36;
587	    return {
588	      key: col.key, color: col.color, label: col.label,
589	      x: Math.min(...xs) - pad,
590	      y: Math.min(...ys) - pad,
591	      w: Math.max(...xs) - Math.min(...xs) + pad * 2,
592	      h: Math.max(...ys) - Math.min(...ys) + pad * 2,
593	    };
594	  }).filter(Boolean);
595	
596	  colBg.selectAll('rect').data(rects, d => d.key)
597	    .join('rect')
598	    .attr('x', d => d.x).attr('y', d => d.y)
599	    .attr('width', d => d.w).attr('height', d => d.h)
600	    .attr('rx', 12)
601	    .attr('fill', d => d.color + '0a')
602	    .attr('stroke', d => d.color + '18')
603	    .attr('stroke-width', 1)
604	    .attr('stroke-dasharray', '4 4');
605	
606	  colLbls.selectAll('text').data(rects, d => d.key)
607	    .join('text')
608	    .attr('class', 'col-lbl')
609	    .attr('x', d => d.x + d.w / 2)
610	    .attr('y', d => d.y + 16)
611	    .attr('text-anchor', 'middle')
612	    .attr('fill', d => d.color)
613	    .text(d => d.label.toUpperCase());
614	}
615	
616	// ── Zoom / pan ────────────────────────────────────────
617	const zoom = d3.zoom().scaleExtent([0.08, 5]).on('zoom', e => g.attr('transform', e.transform));
618	svg.call(zoom);
619	svg.on('click', () => clearHighlight());
620	
621	// ── Fit all ───────────────────────────────────────────
622	function fitAll() {
623	  const b = g.node().getBBox();
624	  if (!b.width || !b.height) return;
625	  const pad = 40;
626	  const scale = Math.min((W() - pad * 2) / b.width, (H() - pad * 2) / b.height, 1.5);
627	  const tx = W() / 2 - scale * (b.x + b.width / 2);
628	  const ty = H() / 2 - scale * (b.y + b.height / 2);
629	  svg.transition().duration(700).call(zoom.transform, d3.zoomIdentity.translate(tx, ty).scale(scale));
630	}
631	
632	sim.on('end', () => setTimeout(fitAll, 50));
633	
634	document.getElementById('btn-fit').addEventListener('click', fitAll);
635	document.getElementById('btn-reset').addEventListener('click', () => {
636	  clearHighlight();
637	  svg.transition().duration(500).call(zoom.transform, d3.zoomIdentity);
638	});
639	
640	// ═══════════════════════════════════════════════════════
641	// HIGHLIGHT
642	// ═══════════════════════════════════════════════════════
643	let activeNode = null;
644	
645	function toggleNode(id) {
646	  if (activeNode === id) { clearHighlight(); return; }
647	  activeNode = id;
648	  applyHighlight(new Set([id]), 'node');
649	  syncSidebar(id);
650	}
651	
652	function highlightFile(fileId) {
653	  activeNode = null;
654	  const ids = new Set(NODES.filter(n => n.file === fileId).map(n => n.id));
655	  applyHighlight(ids, 'file');
656	  document.querySelectorAll('.sb-fn').forEach(el => {
657	    el.classList.toggle('active', ids.has(el.dataset.nid));
658	  });
659	}
660	
661	function applyHighlight(seedIds, mode) {
662	  const connected = new Set(seedIds);
663	  const edgeSet   = new Set();
664	
665	  linkData.forEach((l, i) => {
666	    const inSeed = seedIds.has(l.source.id) || seedIds.has(l.target.id);
667	    if (inSeed) {
668	      connected.add(l.source.id);
669	      connected.add(l.target.id);
670	      edgeSet.add(i);
671	    }
672	  });
673	
674	  nodeG.classed('hi',  d => seedIds.has(d.id))
675	       .classed('dim', d => !connected.has(d.id));
676	
677	  edgeSel.classed('hi',  (d, i) => edgeSet.has(i))
678	         .classed('dim', (d, i) => !edgeSet.has(i));
679	
680	  edgeLbl.classed('hi',  (d, i) => edgeSet.has(i))
681	         .classed('dim', (d, i) => !edgeSet.has(i));
682	
683	  edgePath.attr('marker-end', (d, i) =>
684	    edgeSet.has(i) ? `url(#arr-${d.source.cat}-hi)` : `url(#arr-${d.source.cat})`);
685	}
686	
687	function clearHighlight() {
688	  activeNode = null;
689	  nodeG.classed('hi', false).classed('dim', false);
690	  edgeSel.classed('hi', false).classed('dim', false);
691	  edgeLbl.classed('hi', false).classed('dim', false);
692	  edgePath.attr('marker-end', d => `url(#arr-${d.source.cat})`);
693	  document.querySelectorAll('.sb-fn').forEach(el => el.classList.remove('active'));
694	}
695	
696	function syncSidebar(id) {
697	  document.querySelectorAll('.sb-fn').forEach(el => {
698	    el.classList.toggle('active', el.dataset.nid === id);
699	  });
700	}
701	
702	// ═══════════════════════════════════════════════════════
703	// TOOLTIP
704	// ═══════════════════════════════════════════════════════
705	const tip = document.getElementById('tip');
706	let tipNode = null;
707	
708	function showTip(e, d) {
709	  tipNode = d;
710	  const outs = linkData.filter(l => l.source.id === d.id);
711	  const ins  = linkData.filter(l => l.target.id === d.id);
712	
713	  let html = `<div class="t-title">${d.label}</div>
714	    <div class="t-file">${d.file}</div>
715	    <div class="t-desc">${d.desc}</div>`;
716	
717	  if (outs.length) {
718	    html += `<div class="t-section"><div class="t-sec-lbl">Calls / writes</div>`;
719	    outs.forEach(l => { html += `<div class="t-row">→ ${l.target.label} <span>${l.lbl}</span></div>`; });
720	    html += '</div>';
721	  }
722	  if (ins.length) {
723	    html += `<div class="t-section"><div class="t-sec-lbl">Called / read by</div>`;
724	    ins.forEach(l => { html += `<div class="t-row">← ${l.source.label} <span>${l.lbl}</span></div>`; });
725	    html += '</div>';
726	  }
727	
728	  tip.innerHTML = html;
729	  tip.style.display = 'block';
730	  positionTip(e);
731	}
732	
733	function moveTip(e) { if (tipNode) positionTip(e); }
734	function hideTip()  { tip.style.display = 'none'; tipNode = null; }
735	
736	function positionTip(e) {
737	  const r = container.getBoundingClientRect();
738	  let x = e.clientX - r.left + 14, y = e.clientY - r.top - 10;
739	  if (x + 280 > r.width)  x -= 300;
740	  if (y + 260 > r.height) y -= 240;
741	  tip.style.left = x + 'px';
742	  tip.style.top  = y + 'px';
743	}
744	
745	// ═══════════════════════════════════════════════════════
746	// SEARCH
747	// ═══════════════════════════════════════════════════════
748	document.getElementById('q').addEventListener('input', e => {
749	  const q = e.target.value.trim().toLowerCase();
750	  if (!q) { clearHighlight(); return; }
751	  const matched = new Set(
752	    NODES.filter(n =>
753	      n.label.toLowerCase().includes(q) ||
754	      n.file.toLowerCase().includes(q) ||
755	      n.desc.toLowerCase().includes(q)
756	    ).map(n => n.id)
757	  );
758	  if (matched.size === 0) return;
759	  applyHighlight(matched, 'search');
760	  document.querySelectorAll('.sb-fn').forEach(el => {
761	    el.classList.toggle('active', matched.has(el.dataset.nid));
762	  });
763	});
764	
765	// ═══════════════════════════════════════════════════════
766	// RESIZE
767	// ═══════════════════════════════════════════════════════
768	window.addEventListener('resize', () => {
769	  sim.force('x', d3.forceX(d => CAT[d.cat].colX * W()).strength(0.55))
770	     .force('y', d3.forceY(H() / 2).strength(0.05))
771	     .alpha(0.3).restart();
772	});
773	</script>
774	</body>
775	</html>
